/**
 * Bundled demo data (generated by `agentval seed && agentval export-demo`).
 * Used when the FastAPI backend is not configured or unreachable, e.g. a Vercel
 * deployment of the web app on its own.
 */
import raw from "./demo-data.json";
import type { Dataset, DatasetDetail, EvalResult, Run, RunDetail } from "./types";

const data = raw as unknown as { datasets: DatasetDetail[]; runs: RunDetail[] };

function stripResults(r: RunDetail): Run {
  // eslint-disable-next-line @typescript-eslint/no-unused-vars
  const { results, ...run } = r;
  return run;
}

export const demo = {
  listDatasets(): Dataset[] {
    return data.datasets.map((d) => {
      // eslint-disable-next-line @typescript-eslint/no-unused-vars
      const { testCases, ...rest } = d;
      return rest;
    });
  },
  getDataset(id: string): DatasetDetail | undefined {
    return data.datasets.find((d) => d.id === id);
  },
  listRuns(datasetId?: string): Run[] {
    return data.runs.filter((r) => !datasetId || r.datasetId === datasetId).map(stripResults);
  },
  getRun(id: string): RunDetail | undefined {
    return data.runs.find((r) => r.id === id);
  },
  getResult(runId: string, resultId: string): EvalResult | undefined {
    return this.getRun(runId)?.results.find((r) => r.id === resultId);
  },
};
